let wasmMod = null;

/**
 * Initialize the wasm module compiled by wasm-pack.
 * By default, resolves ../raft-wasm/pkg/raft_wasm_bg.wasm relative to this file.
 * @param {string|URL|Response|BufferSource|WebAssembly.Module} [customWasmUrl]
 * @returns {Promise<object>} resolved wasm JS module exports (including the FFI functions)
 */
export async function loadWasm(customWasmUrl) {
  // Prefer Node CJS require to avoid ESM interop edge cases and ensure we get the plain exports object
  try {
    const { createRequire } = await import('module');
    const require = createRequire(import.meta.url);
    const api = require('./wasm/raft_wasm.cjs');
    wasmMod = api;
    return wasmMod;
  } catch (e) {
    // Fallback to dynamic import below
  }

  // Dynamically import the wasm-pack generated JS glue (works in many environments)
  const mod = await import('./wasm/raft_wasm.cjs');
  // In Node.js target, importing a CommonJS module via ESM yields mod.default === module.exports (object of exports)
  // For other targets (bundler/web), there may be an init function to call.
  const ns = (mod && mod.default) ? mod.default : mod;

  // If there's an init function, call it with the wasm URL; otherwise assume sync init (nodejs target)
  if (typeof ns === 'function') {
    const wasmUrl = customWasmUrl || new URL('./wasm/raft_wasm_bg.wasm', import.meta.url);
    await ns(wasmUrl);
    wasmMod = mod;
  } else if (ns && typeof ns.init === 'function') {
    const wasmUrl = customWasmUrl || new URL('./wasm/raft_wasm_bg.wasm', import.meta.url);
    await ns.init(wasmUrl);
    wasmMod = ns;
  } else {
    // nodejs target: exports are ready to use without explicit init
    wasmMod = ns;
  }

  return wasmMod;
}

/**
 * Returns the initialized wasm module exports.
 * Throws if loadWasm() has not been called successfully.
 */
export function wasmReady() {
  if (!wasmMod) {
    throw new Error('WASM not initialized. Call loadWasm() first.');
  }
  return wasmMod;
}

/**
 * Convenience to check if wasm is initialized.
 */
export function isWasmReady() {
  return !!wasmMod;
}

/**
 * Ready promise for consumers: ensures the WASM module is loaded once.
 * Optional customWasmUrl mirrors loadWasm.
 */
export async function ready(customWasmUrl) {
  if (!isWasmReady()) {
    await loadWasm(customWasmUrl);
  }
}

/**
 * Best-effort shutdown of the WASM runtime and its JS glue.
 * - Calls any exposed cleanup if available (e.g. freeAll)
 * - Clears the Node require cache for the CJS glue to drop references
 * - Nulls out the local singleton so a future loadWasm() can re-init cleanly
 * - Safe to call multiple times
 */
import { shutdownWorkers } from './workerRegistry.mjs';

const STRICT_SHUTDOWN = String(process.env.RAFT_STRICT_SHUTDOWN || '').toLowerCase() === '1';

function summarizeHandles() {
  if (typeof process._getActiveHandles !== 'function') return [];
  const handles = process._getActiveHandles();
  return handles.map((h) => {
    const name = (h && h.constructor && h.constructor.name) || typeof h;
    const info = { name };
    try {
      if ((name === 'Timeout' || name === 'Immediate') && typeof h.hasRef === 'function') {
        info.ref = h.hasRef() ? 1 : 0;
      }
      if (name === 'Socket') {
        info.local = { address: h.localAddress, port: h.localPort };
        info.remote = { address: h.remoteAddress, port: h.remotePort };
        if (typeof h.hasRef === 'function') info.ref = h.hasRef() ? 1 : 0;
      }
      if (name === 'Worker') {
        info.threadId = h.threadId;
      }
      if (name === 'MessagePort' && typeof h.hasRef === 'function') {
        info.ref = h.hasRef() ? 1 : 0;
      }
    } catch (_e) {
      // ignore metadata errors
    }
    return info;
  });
}

function cleanupKnownHandles() {
  if (typeof process._getActiveHandles !== 'function') return;
  const handles = process._getActiveHandles();

  for (const h of handles) {
    const name = (h && h.constructor && h.constructor.name) || typeof h;

    if (name === 'MessagePort') {
      try {
        if (typeof h.close === 'function') {
          h.close();
          // eslint-disable-next-line no-console
          console.log('[raft-logic][debug] closed lingering MessagePort');
        }
      } catch (err) {
        console.warn('[raft-logic][warn] failed to close MessagePort:', err && err.message);
      }
      continue;
    }

    if (name === 'Socket') {
      try {
        if (typeof h.unref === 'function') {
          h.unref();
        }
      } catch (_e) {
        // ignore
      }
      continue;
    }

    if (name === 'Timeout' || name === 'Immediate') {
      try {
        if (typeof h.unref === 'function') {
          h.unref();
        }
      } catch (_e) {
        // ignore
      }
      continue;
    }
  }
}

function diagnoseHandles() {
  const handles = summarizeHandles();
  if (!handles.length) return { ok: true, handles: [] };

  const byName = handles.reduce((m, h) => {
    const key = h.name || 'unknown';
    m[key] = (m[key] || 0) + 1;
    return m;
  }, {});

  console.warn('[raft-logic][warn] lingering handles after shutdown:', {
    total: handles.length,
    byName,
    handles,
  });

  if (STRICT_SHUTDOWN) {
    const err = new Error('Lingering handles after raft-logic shutdown');
    // @ts-ignore
    err.handles = handles;
    throw err;
  }

  return { ok: false, handles };
}

export async function shutdownWasm() {
  // Attempt module-level cleanup if provided
  try {
    if (wasmMod && typeof wasmMod.freeAll === 'function') {
      // If the module ever exposes a global freeAll, call it
      await wasmMod.freeAll();
    }
  } catch (_e) {
    // ignore cleanup errors on best-effort shutdown
  }

  // Drop the singleton first so user-land stops using it
  wasmMod = null;

  // If we loaded via Node CJS require, evict it from require.cache
  // so the WebAssembly.Instance can be GC'ed and any underlying resources released.
  try {
    const { createRequire } = await import('module');
    const req = createRequire(import.meta.url);
    const resolved = req.resolve('./wasm/raft_wasm.cjs');
    if (req.cache && req.cache[resolved]) {
      delete req.cache[resolved];
    }
  } catch (_e) {
    // Dynamic import path didn't use CJS require; nothing to evict.
  }

  // Hint GC in environments where it's enabled (node --expose-gc); ignore if not available.
  try {
    if (typeof global !== 'undefined' && typeof global.gc === 'function') {
      global.gc();
    }
  } catch (_e) {
    // ignore
  }

  // Terminate all active workers
  await shutdownWorkers();

  if (typeof process._getActiveHandles === 'function') {
    // Best-effort cleanup of known handle types (MessagePort, Socket, timers)
    cleanupKnownHandles();
    // Log and optionally throw if handles remain, but never force process.exit()
    diagnoseHandles();
  }
}

/**
 * Unified shutdown for both WASM runtime and worker threads.
 */
export async function shutdownAll() {
  await shutdownWasm();
  await shutdownWorkers();
}

/**
 * --- WASM Lifecycle Control and Diagnostics ---
 */

if (!globalThis.__raftWasmState) {
  globalThis.__raftWasmState = {
    instance: null,
    refCount: 0,
    freed: false,
    autoFreeDisabled: false,
  };
}

/**
 * Disable automatic freeing of the WASM runtime.
 */
export function disableAutoFree() {
  globalThis.__raftWasmState.autoFreeDisabled = true;
}

/**
 * Alias for disableAutoFree(true)
 */
export function retainWasm(retain = true) {
  globalThis.__raftWasmState.autoFreeDisabled = !!retain;
}

/**
 * Get or load the global WASM instance.
 */
export async function getWasmInstance(options = {}) {
  const state = globalThis.__raftWasmState;
  if (state.instance && !state.freed) {
    return state.instance;
  }
  const mod = await loadWasm(options.customWasmUrl);
  state.instance = mod;
  state.freed = false;
  return mod;
}

/**
 * Return diagnostic information about the WASM runtime.
 */
export function getWasmStatus() {
  const s = globalThis.__raftWasmState;
  return {
    refCount: s.refCount,
    freed: s.freed,
    autoFreeDisabled: s.autoFreeDisabled,
  };
}

/**
 * Override shutdownWasm to respect disableAutoFree.
 */
const _originalShutdownWasm = shutdownWasm;
export async function controlledShutdownWasm() {
  const s = globalThis.__raftWasmState;
  if (s.autoFreeDisabled) {
    console.log('[raft-logic] Auto-free disabled; skipping WASM shutdown');
    return;
  }
  await _originalShutdownWasm();
  s.freed = true;
  s.instance = null;
}
